package com.print.kiosk.controller;
import com.print.kiosk.dto.response.*;import com.print.kiosk.entity.*;import com.print.kiosk.service.interfaces.*;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/agent/queue") public class AgentQueueController{private final QueueService queue;private final RequestProcessingService processing;public AgentQueueController(QueueService q,RequestProcessingService p){queue=q;processing=p;}@GetMapping public ResponseEntity<Page<QueueEntryResponse>> queue(@RequestParam(required=false)String search,@RequestParam(required=false)PaymentStatus paymentStatus,@RequestParam(required=false)PrintRequestStatus requestStatus,@PageableDefault(size=20)Pageable pageable){return ResponseEntity.ok(queue.getAgentQueue(search,paymentStatus,requestStatus,pageable));}@GetMapping("/exceptions")public ResponseEntity<Page<ExceptionQueueResponse>> exceptions(@PageableDefault(size=20)Pageable pageable){return ResponseEntity.ok(queue.getExceptionQueue(pageable));}@PostMapping("/claim-next")public ResponseEntity<RequestActionResponse> claim(@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok(processing.claimNext(id(jwt)));}private Long id(Jwt jwt){Number n=jwt.getClaim("accountId");if(n==null)throw new IllegalArgumentException("Authenticated account ID is missing");return n.longValue();}}